SELECT "deal_name" AS "deal_name", "deal_id" AS "deal_id", "deal_size" AS "deal_size", "investor_count" AS "investor_count", COUNT("deal_id") AS "row_count" FROM "bds_dg_oraas"."dgstream"."vw_deal_summary" WHERE "product" = __P_f0__ AND UPPER("offering_type") LIKE UPPER(__P_f1__) AND "investor_count" >= __P_f2__ AND "deal_name" IS NOT NULL AND "last_priced" >= __P_f4__ GROUP BY "deal_name", "deal_id", "deal_size", "investor_count" ORDER BY "deal_size" DESC LIMIT 5
